  const anterior = mapa.has(producto.categoria)
    ? mapa.get(producto.categoria)
    : { categoria: producto.categoria, productos: 0, stock: 0 };
  mapa.set(producto.categoria, {
    categoria: producto.categoria,
    productos: anterior.productos + 1,
    stock: anterior.stock + producto.stock
